// ---------------------------------------------------------------------------
// Aplana el sobre que manda Meta. Un solo POST puede traer varios eventos y de
// dos clases distintas: mensajes entrantes y acuses de entrega (statuses).
// Devuelve un item por evento, ya etiquetado.
// ---------------------------------------------------------------------------
const eventos = [];

for (const item of $input.all()) {
  const cuerpo = item.json.body ?? item.json;
  for (const entrada of (cuerpo.entry ?? [])) {
    for (const cambio of (entrada.changes ?? [])) {
      const v = cambio.value ?? {};
      const phoneNumberId = v.metadata?.phone_number_id ?? '';

      for (const m of (v.messages ?? [])) {
        // El nombre del perfil de WhatsApp sirve de respaldo si el cliente
        // no está en la hoja todavía.
        const perfil = (v.contacts ?? []).find(c => c.wa_id === m.from);
        eventos.push({ json: {
          clase: 'mensaje',
          phone_number_id: phoneNumberId,
          from: String(m.from ?? ''),
          wamid: String(m.id ?? ''),
          tipo_mensaje: String(m.type ?? ''),
          // Las quick replies de una plantilla llegan como type=button con payload.
          payload_boton: m.button?.payload ?? m.interactive?.button_reply?.id ?? '',
          texto: m.text?.body ?? m.button?.text ?? m.interactive?.button_reply?.title ?? '',
          nombre_perfil: perfil?.profile?.name ?? '',
          timestamp: m.timestamp ?? '',
        }});
      }

      for (const s of (v.statuses ?? [])) {
        eventos.push({ json: {
          clase: 'estado',
          phone_number_id: phoneNumberId,
          wamid: String(s.id ?? ''),
          estado_entrega: String(s.status ?? ''),
          destinatario: String(s.recipient_id ?? ''),
          // Aquí viene el dato que de verdad importa para la contabilidad:
          // si Meta lo facturó y en qué categoría lo clasificó ELLA, que no
          // siempre coincide con la categoría con la que se envió.
          facturable: s.pricing?.billable === true ? 'si'
                    : s.pricing?.billable === false ? 'no' : '',
          categoria_real: s.pricing?.category ?? '',
          motivo_error: (s.errors ?? []).map(e => e.code + ': ' + (e.title ?? '')).join(' | '),
          timestamp: s.timestamp ?? '',
        }});
      }
    }
  }
}

console.log('eventos=' + JSON.stringify(eventos.map(e => e.json.clase)));
return eventos;

// ---------------------------------------------------------------------------
// Decide qué hacer con una respuesta entrante: identifica al cliente, deduce la
// intención y arma los tres mensajes posibles (respuesta al cliente, aviso al
// dueño) más la fila de log. Corre una vez por item.
// ---------------------------------------------------------------------------
const ev       = $json;
const negocios = $('Leer negocios').all().map(i => i.json);
const clientes = $('Leer clientes').all().map(i => i.json);

const soloDigitos = t => String(t ?? '').replace(/[^0-9]/g, '');

// WhatsApp no siempre devuelve el número tal como se envió. México inserta o
// quita un "1" tras el 52, y Argentina un "9" tras el 54. Si comparamos el
// número crudo, el 100% de las respuestas mexicanas quedan sin identificar.
function variantes(tel) {
  const d = soloDigitos(tel);
  const v = new Set([d]);
  if (d.startsWith('521') && d.length === 13) v.add('52' + d.slice(3));
  if (d.startsWith('52')  && d.length === 12) v.add('521' + d.slice(2));
  if (d.startsWith('549') && d.length === 13) v.add('54' + d.slice(3));
  if (d.startsWith('54')  && d.length === 12) v.add('549' + d.slice(2));
  return [...v];
}

const indice = {};
for (const c of clientes) {
  for (const k of variantes(c.telefono)) {
    if (k.length >= 10) indice[k] = c;
  }
}

let cliente = null;
for (const k of variantes(ev.from)) {
  if (indice[k]) { cliente = indice[k]; break; }
}

// Si no está en la hoja, seguimos igualmente: el dueño debe enterarse de que
// alguien escribió, aunque no sepamos quién es.
const negocioId = cliente ? String(cliente.negocio_id).trim() : '';
const negocio = negocios.find(n => String(n.negocio_id).trim() === negocioId)
             || negocios.find(n => String(n.phone_number_id).trim() === String(ev.phone_number_id).trim())
             || {};

const nombre = String(cliente?.nombre ?? ev.nombre_perfil ?? '').trim().split(/\s+/)[0] || 'Hola';
const negocioCorto = String(negocio.nombre_corto || negocio.nombre || 'la barbería').trim();

// Intención: primero el payload del botón (determinista), y solo si no hay
// botón caemos a interpretar texto libre.
const normalizar = s => String(s ?? '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const PALABRAS_BAJA = ['baja','stop','cancelar suscripcion','no me escriban','no quiero mensajes','eliminar','desuscribir','unsubscribe'];
const PALABRAS_SI   = ['si','sii','claro','va','dale','agendame','agenda','quiero','sale','ok','okay','de una','me interesa','apartame','apartar'];
const PALABRAS_NO   = ['no','ahora no','luego','despues','mas adelante','no gracias','todavia no'];

const texto = normalizar(ev.texto);
let intencion;
if (ev.payload_boton) {
  intencion = ({ AGENDAR: 'agendar', AHORA_NO: 'ahora_no', BAJA: 'baja' })[ev.payload_boton] ?? 'otro';
} else if (PALABRAS_BAJA.some(p => texto === p || texto.includes(p))) {
  intencion = 'baja';
} else if (PALABRAS_SI.some(p => texto === p || texto.startsWith(p + ' '))) {
  intencion = 'agendar';
} else if (PALABRAS_NO.some(p => texto === p || texto.startsWith(p + ' '))) {
  intencion = 'ahora_no';
} else {
  // Texto libre que no encaja: no adivinamos, lo pasa un humano.
  intencion = 'otro';
}

const RESPUESTAS = {
  baja:     'Listo, no volverás a recibir mensajes nuestros. Si algún día quieres volver, aquí estaremos. 👋',
  agendar:  '¡Excelente, ' + nombre + '! 🙌 En un momento te escriben de ' + negocioCorto + ' para darte hora.',
  ahora_no: 'Sin problema, ' + nombre + '. Aquí seguimos cuando lo necesites. ✂️',
  otro:     'Gracias por escribir, ' + nombre + '. Ya avisamos a ' + negocioCorto + ' y te contactan enseguida.',
};

const telefonoCliente = soloDigitos(ev.from);
const phoneNumberId = String(ev.phone_number_id || negocio.phone_number_id || '').trim();

const respuestaCliente = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: telefonoCliente,
  type: 'text',
  text: { preview_url: false, body: RESPUESTAS[intencion] },
};

// Al dueño solo lo molestamos cuando hay algo que hacer: un cliente que
// quiere cita o un mensaje que necesita lectura humana.
const avisarDueno = (intencion === 'agendar' || intencion === 'otro')
  && !!soloDigitos(negocio.telefono_dueno)
  && !!String(negocio.plantilla_aviso || '').trim();

const avisoDueno = avisarDueno ? {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: soloDigitos(negocio.telefono_dueno),
  type: 'template',
  template: {
    name: String(negocio.plantilla_aviso).trim(),
    language: { code: String(negocio.idioma_plantilla || 'es_MX').trim() },
    components: [{ type: 'body', parameters: [
      { type: 'text', text: negocioCorto },
      { type: 'text', text: String(cliente?.nombre ?? ev.nombre_perfil ?? 'Un cliente').trim() },
      { type: 'text', text: telefonoCliente },
    ]}],
  },
} : null;

return { json: {
  intencion,
  encontrado: !!cliente,
  cliente_id: cliente ? String(cliente.cliente_id).trim() : '',
  negocio_id: negocioId,
  telefono: telefonoCliente,
  phone_number_id: phoneNumberId,
  // Solo tocamos la ficha del cliente si lo identificamos.
  actualizar_cliente: !!cliente,
  nuevo_optout: intencion === 'baja' ? 'si' : String(cliente?.optout ?? 'no'),
  nuevo_estado: intencion === 'baja' ? 'baja'
              : intencion === 'agendar' ? 'interesado'
              : intencion === 'ahora_no' ? 'contactado'
              : 'respondio',
  respuesta_cliente: respuestaCliente,
  avisar_dueno: avisarDueno,
  aviso_dueno: avisoDueno,
  fila_log: {
    timestamp: new Date().toISOString(),
    negocio_id: negocioId,
    cliente_id: cliente ? String(cliente.cliente_id).trim() : '',
    telefono: telefonoCliente,
    tipo: 'respuesta',
    categoria: 'service',
    plantilla: '',
    wamid: ev.wamid,
    estado: 'recibido',
    error_code: '',
    error_mensaje: '',
    // Responder dentro de la ventana de 24h no cuesta nada.
    costo_estimado_usd: 0,
    facturable: 'no',
    respondio: 'si',
    agendo: intencion === 'agendar' ? 'si' : 'no',
    dias_dormido: '',
    diagnostico: 'intencion=' + intencion + (cliente ? '' : ' (número no identificado en la hoja de clientes)'),
    accion: cliente ? 'ninguna' : 'avisar_operador',
  },
}};

// ---------------------------------------------------------------------------
// Acuse de entrega. Aquí llega el único dato de costo que no es una estimación:
// Meta dice si el mensaje fue facturable y en qué categoría lo clasificó.
// Se escribe sobre la fila del log que tenga ese wamid.
// ---------------------------------------------------------------------------
const ev = $json;

// sent -> delivered -> read. No degradamos un estado ya avanzado.
const RANGO = { enviado: 1, sent: 1, entregado: 2, delivered: 2, leido: 3, read: 3, failed: 0, fallido: 0 };
const ES = { sent: 'enviado', delivered: 'entregado', read: 'leido', failed: 'fallido', deleted: 'borrado' };

const estado = ES[ev.estado_entrega] ?? ev.estado_entrega;

return { json: {
  wamid: ev.wamid,
  estado,
  facturable: ev.facturable,
  categoria: ev.categoria_real || '',
  error_mensaje: ev.motivo_error || '',
  // Un fallo en la entrega es lo que hay que mirar: el envío se aceptó pero
  // el mensaje nunca llegó, y eso no aparece en el log del workflow 01.
  accion: estado === 'fallido' ? 'avisar_operador' : 'ninguna',
  rango: RANGO[ev.estado_entrega] ?? 0,
}};
